css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .72); position: relative; }
.loader .press { position: absolute; left: 12%; right: 12%; top: 4%; height: 22%; border-radius: 6px; background: linear-gradient(var(--accent-2), var(--accent)); animation: punch-down calc(var(--loader-speed) * 1.6) cubic-bezier(.5, 0, .3, 1) infinite; }
.loader .press::after { content: ''; position: absolute; left: 14%; right: 14%; top: 100%; height: 34%; border-radius: 0 0 3px 3px; background: #64748b; }
.loader .sheet { position: absolute; left: 8%; bottom: 10%; width: 84%; height: 42%; border-radius: 4px; background: color-mix(in srgb, var(--accent-2) 45%, #f8fafc); box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 25%, transparent); }
.loader i { position: absolute; bottom: 26%; width: 11%; height: 15%; border-radius: 50%; background: color-mix(in srgb, #0f172a 60%, transparent); transform: scale(0); animation: punch-hole calc(var(--loader-speed) * 1.6) ease-out infinite; }
.loader i:nth-of-type(1) { left: 22%; }
.loader i:nth-of-type(2) { left: 45%; }
.loader i:nth-of-type(3) { left: 68%; }
@keyframes punch-down { 0%, 100% { transform: translateY(0); } 42%, 54% { transform: translateY(58%); } }
@keyframes punch-hole { 0%, 44% { transform: scale(0); } 54%, 84% { transform: scale(1); } 96%, 100% { transform: scale(0); } }
